// Agent 面板这一轮放在自己数据目录里的桥接扩展：把面板的工具（MCP）交给 Pi，跑完就删掉
import { request } from 'node:http'

const url = new URL('{url}')
let seq = 0

// 扩展加载总共最多等这么久：Pi 启动时会等扩展加载完才读 stdin，面板这时在等 get_state（默认 15 秒）。
// 留 5 秒给 Pi 冷启动 + 读 stdin + 回包，别把两边顶到同一条线上
const LOAD_BUDGET_MS = {loadBudget}
// 单次请求（握手、列工具）最多等这么久：面板正忙（压缩上下文、写大对话）时会晚几秒才回，超时就再试一次；
// 两次共用上面那份总预算，不会越等越久
const STEP_TIMEOUT_MS = {stepTimeout}
const STEP_ATTEMPTS = {attempts}

// 面板的编排工具每个身份都有这三个（子任务、工作流节点也有）；缺任何一个都说明这一轮拿到的清单不完整。
// 只核对身份无关的：执行计划、收尾合并、后台命令各身份本来就不一样。只在握手声明了这一轮有编排工具时核对：
// 压缩轮、原生审查轮只挂提问工具，清单里本来就没有它们（见 server/ask-mcp.ts 的 initialize）
const CORE_TOOLS = ['get_status', 'send_message', 'read_messages']

// 用 node:http 而不是 fetch：等用户回答提问可能很久，fetch 默认 5 分钟就超时
function rpc(method: string, params: unknown, timeoutMs?: number, what = '请求'): Promise<any> {
  const body = JSON.stringify({ jsonrpc: '2.0', id: ++seq, method, params })
  return new Promise((resolve, reject) => {
    const req = request(
      url,
      { method: 'POST', headers: { 'content-type': 'application/json', accept: 'application/json, text/event-stream' } },
      (res) => {
        let text = ''
        res.setEncoding('utf8')
        res.on('data', (c) => (text += c))
        res.on('end', () => {
          try {
            const raw = text.trim().startsWith('{')
              ? text
              : (text.split('\n').filter((l) => l.startsWith('data:')).pop() ?? '').slice(5)
            const msg = JSON.parse(raw)
            if (msg.error) reject(new Error(msg.error.message))
            else resolve(msg.result)
          } catch {
            reject(new Error(`HTTP ${res.statusCode}: ${text.slice(0, 200)}`))
          }
        })
      },
    )
    // 握手和列工具带超时；tools/call 不带：它要等用户回答、跑长命令，可能很久
    if (timeoutMs) req.setTimeout(timeoutMs, () => req.destroy(new Error(`${what}等了 ${timeoutMs / 1000} 秒还没回应`)))
    req.on('error', reject)
    req.end(body)
  })
}

// 握手和列工具共用一份总预算：面板忙时两边都可能晚回，每一步超时后再试一次
function call(method: string, params: unknown, what: string, startedAt: number): Promise<any> {
  let attempt = 1
  const once = (): Promise<any> => {
    const left = LOAD_BUDGET_MS - (Date.now() - startedAt)
    if (left <= 0) return Promise.reject(new Error(`${what}总共等了 ${LOAD_BUDGET_MS / 1000} 秒还没回应`))
    return rpc(method, params, Math.min(STEP_TIMEOUT_MS, left), what).catch((e) => {
      if (++attempt > STEP_ATTEMPTS) throw e
      return once()
    })
  }
  return once()
}

export default async function (pi: any) {
  const startedAt = Date.now()
  let tools: any[] = []
  // 一处失败就整批工具都不在（不是一个两个被裁掉）：统一从这里报给面板，
  // 不然模型只会自己写一句「工具不可见」再退化成用普通命令，用户看不出原因
  const fail = (error: string) => {
    console.error(`agent-panel: ${error}`)
    pi.on('session_start', (_event: unknown, ctx: any) => ctx.ui.setStatus('agent-panel-tools', error))
  }
  try {
    const hello = await call('initialize', { protocolVersion: '2025-03-26', capabilities: {}, clientInfo: { name: 'pi', version: '1' } }, '握手', startedAt)
    // 这一轮有没有编排工具由面板在握手里声明（capabilities.experimental.orchestration）：
    // 不按服务名猜，压缩轮、原生审查轮只有提问工具时就不会被当成清单不完整
    const orchestration = hello?.capabilities?.experimental?.orchestration?.enabled === true
    const listed = await call('tools/list', {}, '列工具', startedAt)
    tools = listed?.tools ?? []
    // 列到了却一个也没有：同样要让用户知道，不能静默地一个都不注册
    if (!tools.length) fail('面板没有返回任何面板工具')
    else if (orchestration) {
      const missing = CORE_TOOLS.filter((name) => !tools.some((tool: any) => tool.name === name))
      if (missing.length) fail(`面板的工具清单不完整，缺 ${missing.join('、')}`)
    }
  } catch (e) {
    fail((e as Error).message)
  }
  for (const tool of tools)
    pi.registerTool({
      name: tool.name,
      label: tool.title ?? tool.name,
      description: tool.description ?? '',
      parameters: tool.inputSchema ?? { type: 'object', properties: {} },
      async execute(_id: string, args: unknown) {
        const r = await rpc('tools/call', { name: tool.name, arguments: args ?? {} })
        const content = (r?.content ?? []).map((c: any) =>
          c.type === 'image'
            ? { type: 'image', data: c.data, mimeType: c.mimeType }
            : { type: 'text', text: c.type === 'text' ? c.text : JSON.stringify(c) },
        )
        if (r?.isError) throw new Error(content.map((c: any) => c.text ?? '').join('\n'))
        return { content, details: {} }
      },
    })
}

